with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, '照夜白図', '韓幹', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/36/%E5%94%90_%E9%9F%93%E5%B9%B9_%E7%85%A7%E5%A4%9C%E7%99%BD%E5%9C%96_%E5%8D%B7-Night-Shining_White_MET_DP153679.jpg/960px-%E5%94%90_%E9%9F%93%E5%B9%B9_%E7%85%A7%E5%A4%9C%E7%99%BD%E5%9C%96_%E5%8D%B7-Night-Shining_White_MET_DP153679.jpg', '唐の宮廷画家・韓幹が8世紀半ば（750年ごろ）に描いたとされる、玄宗皇帝の愛馬「照夜白」の姿です。杭につながれた馬が、たてがみを逆立て、目をむいて身をよじる一瞬をとらえています。色を使わず墨の線とわずかなぼかしだけで描く「白画」の作品で、引き締まった線から馬の気性の荒さが伝わってきます。中国の馬の絵の最高峰のひとつとされ、1977年からメトロポリタン美術館が所蔵しています。', 'CC0', null, 'https://commons.wikimedia.org/wiki/File:唐_韓幹_照夜白圖_卷-Night-Shining_White_MET_DP153679.jpg'),
    (2, 'カラスのいる麦畑', 'フィンセント・ファン・ゴッホ', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/Korenveld_met_kraaien_-_s0149V1962_-_Van_Gogh_Museum.jpg/960px-Korenveld_met_kraaien_-_s0149V1962_-_Van_Gogh_Museum.jpg', 'ゴッホが亡くなる直前の1890年7月、オーヴェール＝シュル＝オワーズで描いた作品で、アムステルダムのファン・ゴッホ美術館が所蔵します。横に長い画面の3分の2を風に揺れる麦畑が占め、荒れた空の下をカラスの群れが飛びます。画面中央の道はどこへも続かないように見え、孤独や不安を感じさせます。最後の作品と言われることもありますが、手紙の記録などから、実際にはこの後にも制作が続いていたと考えられています。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Korenveld_met_kraaien_-_s0149V1962_-_Van_Gogh_Museum.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('彫刻の森美術館で浅田政志の写真展', '写真家・浅田政志が神奈川の町を「横浜写真」の風合いで撮った作品展が、2027年1月から箱根で開かれる。', '神奈川県箱根町の彫刻の森美術館で、写真家・浅田政志による展覧会「カナガワ ポトガラヒー 出張浅田撮影局｜箱根編」が2027年1月16日から3月22日まで開かれる。神奈川県民ホールの県域展開事業として、浅田が県内各地へ出張し、人や風景、町を撮影するプロジェクト。写真は、明治期に外国人向けの土産物として人気を集めた手彩色の「横浜写真」をモチーフに、モノクロ写真へデジタルで色を付けた風合いに仕上げられている。会場の「丸太広場キトキ」では、箱根町に加え、開成町、真鶴町、中井町の全4町で撮影された作品が展示される。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33336',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('日比谷公園で「Hibiya Art Park 2026」', '建築家・永山祐子がディレクターを務める屋外アートイベントが、11月29日まで日比谷公園で開かれている。', '東京・日比谷公園で、屋外アートイベント「Hibiya Art Park 2026 - Timeless Phenomena 確かにありそうなもの -」が11月13日から29日まで開かれている。東京都が進める「花と光のムーブメント」の一環で、今年は建築家の永山祐子がディレクターを務める。1903年の開園以来、東京の変化を見つめてきた公園を舞台に、見過ごされがちな自然や生き物、人々の営みに目を向けるのがテーマ。栗林隆、佐々木類、横手太紀の3名が参加し、会期中には花崎草による参加型パフォーマンス《花束往還》も行われる。入場は無料。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33313',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('「ARTE TOKYO」臨海エリアが本格始動', '東京の文化芸術祭「ARTE TOKYO」の臨海エリアで、お台場の水辺を舞台にした作品の公開が本格的に始まった。', '東京の都市空間を舞台とする文化芸術祭「ARTE TOKYO（アルテ・トーキョー）」の臨海エリアで、11月7日から新たに4つのプログラムが始まり、10月から公開中の作品とあわせて5つのコアプログラムが展開されている。おだいばビーチでは、真鍋大度とカイル・マクドナルドによる《Alloscape》や、東京湾の廃棄漁網を素材にした永山祐子の《うみのハンモック》を公開。湯浅良介とGROUPの《風船と椅子》、鈴木康広の《ファスナーの船》、齋藤精一の《JIKU #024 TELEPORT BRIDGE》も並ぶ。多くの作品は12月31日まで公開される。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/headline/33312',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('穀物の収穫', 'The Harvesters', 'ピーテル・ブリューゲル（父）', 'Pieter Bruegel the Elder',
        1565,
        (select slug from public.art_movements where slug = 'renaissance'),
        'メトロポリタン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Pieter_Bruegel_the_Elder-_The_Harvesters_-_Google_Art_Project.jpg/960px-Pieter_Bruegel_the_Elder-_The_Harvesters_-_Google_Art_Project.jpg', '1565年、アントウェルペンの商人ニコラース・ヨンゲリンクの注文で描かれた、季節の移り変わりを表す連作の1点です。連作は6点（12点とも）あったとされ、残る5点のうち「雪中の狩人」など3点はウィーン、この作品はニューヨークのメトロポリタン美術館にあります。真夏の麦畑で、刈り取りをする人と木陰でパンやチーズを食べる人が描かれ、奥には池で水浴びする人や遠くの船まで広がります。宗教的な主題を離れ、農民の働く姿と風景そのものを主役にした点で、近代的な風景画の先駆けと評されています。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Pieter_Bruegel_the_Elder-_The_Harvesters_-_Google_Art_Project.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('メズタン', 'Mezzetin', 'アントワーヌ・ヴァトー', 'Antoine Watteau',
        1718,
        (select slug from public.art_movements where slug = 'rococo'),
        'メトロポリタン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9c/Jean-Antoine_Watteau_-_Mezzetin.JPG/960px-Jean-Antoine_Watteau_-_Mezzetin.JPG', 'イタリアの即興喜劇コメディア・デラルテの登場人物メズタン（メッゼッティーノ）を描いた、ヴァトー晩年の作品です。縞模様の衣装を着た男が庭園の石のベンチに腰かけ、ギターを抱えて空を仰ぐように歌っています。背後の茂みには、背を向けた女性の石像が置かれ、報われない恋を暗示するとも言われます。歴史画や宗教画が重んじられた時代に、ヴァトーは芝居の人物や恋の場面を軽やかな筆で描き、ロココ絵画の扉を開きました。ニューヨークのメトロポリタン美術館が所蔵しています。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Jean-Antoine_Watteau_-_Mezzetin.JPG')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('雇われ羊飼い', 'The Hireling Shepherd', 'ウィリアム・ホルマン・ハント', 'William Holman Hunt',
        1851,
        (select slug from public.art_movements where slug = 'pre-raphaelite'),
        'マンチェスター美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/William_Holman_Hunt_-_The_Hireling_Shepherd.jpg/960px-William_Holman_Hunt_-_The_Hireling_Shepherd.jpg', '1851年、ハントがサリーの田園で、同じころミレーが「オフィーリア」を描いていたのと近い場所で制作した作品です。羊飼いが若い娘の肩に腕を回してメンガタスズメ（ドクロ模様の蛾）を見せる間に、羊たちは溝を越えて麦畑へ迷い込んでいきます。ロイヤル・アカデミーに出品された際には、シェイクスピア『リア王』の一節が添えられました。草花の一本一本まで明るい色で描き込む細密さは、自然を忠実に写すことを求めたラファエル前派の姿勢をよく示しています。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:William_Holman_Hunt_-_The_Hireling_Shepherd.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
