insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('大きな青い馬', 'The Large Blue Horses', 'フランツ・マルク', 'Franz Marc',
        1911,
        (select slug from public.art_movements where slug = 'expressionism'),
        'ウォーカー・アート・センター', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Franz_Marc_005.jpg/960px-Franz_Marc_005.jpg', '1911年、カンディンスキーらと「青騎士」を結成した年に描かれた、マルクを代表する動物画のひとつです。3頭の青い馬が体を寄せ合い、赤い丘を背に、うねるような曲線で画面いっぱいに描かれています。マルクは色に意味を込め、青を精神性や男性性の色と考えました。見たままの色から離れ、感情や精神を色と形で表そうとした点で、ドイツ表現主義の大切な一歩となった作品です。アメリカ・ミネアポリスのウォーカー・アート・センターが所蔵しています。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Franz_Marc_005.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ウィリアム・ホルマン・ハント', 'William Holman Hunt', 'ハント',
        1827, 1910, 'west', array['pre-raphaelite']::text[],
        'ラファエル前派の創設者のひとりで、最後までその理念を貫いたイギリスの画家。', 'ロンドンのチープサイドに生まれました。はじめは商業の仕事に就きましたが、絵を学び、1843年にロイヤル・アカデミーの付属美術学校に入りました。

1848年、学友のジョン・エヴァレット・ミレー、ダンテ・ゲイブリエル・ロセッティらと「ラファエル前派」を結成しました。古典に偏ったアカデミーの教育に反対し、批評家ジョン・ラスキンの「自然をありのままに写す」という考えに沿って、聖書や伝説に題材をとり、画面のすみずみまで細かく描き込みました。仲間が別の道へ進んだ後も、その特色を最後まで保った画家です。

聖書の場面を描くには現地を見なければならないと考え、パレスチナを3度訪れました。代表作に「雇われ羊飼い」「良心の目覚め」「世の光」「贖罪の山羊」などがあります。', 'https://ja.wikipedia.org/wiki/%E3%82%A6%E3%82%A3%E3%83%AA%E3%82%A2%E3%83%A0%E3%83%BB%E3%83%9B%E3%83%AB%E3%83%9E%E3%83%B3%E3%83%BB%E3%83%8F%E3%83%B3%E3%83%88')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('フランツ・マルク', 'Franz Marc', 'マルク',
        1880, 1916, 'west', array['expressionism']::text[],
        '鮮やかな色で動物を描いた、「青騎士」の創設メンバーのドイツの画家。', 'ミュンヘンで、風景画家の父のもとに生まれました。はじめは神学を志しましたが、1900年からミュンヘン美術アカデミーで学び、パリ滞在中にはゴッホの作品に強く共感しました。

1910年に画家アウグスト・マッケと出会い、翌1911年にはカンディンスキーらと芸術サークル「青騎士」を結成しました。成熟期の作品のほとんどは自然の中の動物で、ほとんどキュビスムのような形と、鮮やかな色が特徴です。青は精神性、黄は歓び、赤は暴力というように、色に感情の意味を込めました。ドローネーや未来派からも影響を受けています。

代表作に「青い馬I」「大きな青い馬」「動物の運命」などがあります。第一次世界大戦に従軍し、1916年にヴェルダンの戦いで戦死しました。のちにナチスから「退廃芸術」とされ、多くの作品が美術館から外されました。', 'https://ja.wikipedia.org/wiki/%E3%83%95%E3%83%A9%E3%83%B3%E3%83%84%E3%83%BB%E3%83%9E%E3%83%AB%E3%82%AF')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('フェルナン・レジェ', 'Fernand Léger', 'レジェ',
        1881, 1955, 'west', array['cubism']::text[],
        '太い輪郭線と単純な形、明快な色で、機械の時代の人間を描いたフランスの画家。', 'フランス・ノルマンディー地方のアルジャンタンに生まれました。建築家のもとで修業したのち1900年にパリへ出て、製図工として働きながら装飾美術学校やアカデミー・ジュリアンに通いました。

1907年のセザンヌ回顧展に大きな影響を受け、キュビスムに加わりました。人物を円筒形に還元した初期の作風は「チュビスム（土管屋）」とからかわれたこともあります。第一次世界大戦に従軍して兵器の機能的な美しさに魅せられ、その後は人物と機械を、太い輪郭線、単純な形、はっきりした色で描く独自の様式を築きました。

絵画のほか、壁画、舞台美術、映画「バレエ・メカニック」、ステンドグラス、陶器など幅広く手がけました。代表作に「森の裸体」「三人の女性」「大パレード」などがあり、晩年に陶器をつくった南仏ビオットにはフェルナン・レジェ美術館が建てられています。', 'https://ja.wikipedia.org/wiki/%E3%83%95%E3%82%A7%E3%83%AB%E3%83%8A%E3%83%B3%E3%83%BB%E3%83%AC%E3%82%B8%E3%82%A7')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
